#!/usr/bin/env bash
# Question 3: Name resolution broken. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q3_NS}" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
timeout 60 bash -c "until kubectl -n '${Q3_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: web
  namespace: ${Q3_NS}
spec:
  replicas: 1
  selector:
    matchLabels: { app: web }
  template:
    metadata:
      labels: { app: web }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
---
apiVersion: v1
kind: Service
metadata:
  name: web
  namespace: ${Q3_NS}
spec:
  selector: { app: web }
  ports: [{ port: 80 }]
EOF
kubectl -n "${Q3_NS}" delete pod client --ignore-not-found --wait=true >/dev/null
kubectl -n "${Q3_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"client"},"spec":{"containers":[{"name":"shell","image":"busybox:1.36","command":["sleep","infinity"]}]}}'
if ! kubectl -n "${Q3_NS}" wait --for=condition=Ready pod/client --timeout=180s; then
  kubectl -n "${Q3_NS}" describe pod/client >&2 || true
  exit 1
fi
kubectl -n "${Q3_NS}" rollout status deployment/web --timeout=180s

case "${Q3_FAULT}" in
  corefile-typo)
    kubectl -n kube-system get configmap coredns -o yaml | sed -E 's#^([[:space:]]*)forward \. /etc/resolv\.conf#\1forwrd . /etc/resolv.conf#' | kubectl replace -f - >/dev/null
    kubectl -n kube-system get configmap coredns -o jsonpath='{.data.Corefile}' | grep -qE -- 'forwrd \. ' || { echo "could not edit the Corefile" >&2; exit 1; }
    kubectl -n kube-system delete pod -l k8s-app=kube-dns --wait=false >/dev/null
    ;;
  scaled-to-zero)
    kubectl -n kube-system scale deployment/coredns --replicas=0
    kubectl -n kube-system wait --for=delete pod -l k8s-app=kube-dns --timeout=120s >/dev/null || true
    ;;
  cluster-domain)
    kubectl -n kube-system get configmap coredns -o yaml | sed -E 's#kubernetes cluster\.local #kubernetes cluster.lab #' | kubectl replace -f - >/dev/null
    kubectl -n kube-system get configmap coredns -o jsonpath='{.data.Corefile}' | grep -qE -- 'kubernetes cluster\.lab ' || { echo "could not edit the Corefile" >&2; exit 1; }
    kubectl -n kube-system rollout restart deployment/coredns
    kubectl -n kube-system rollout status deployment/coredns --timeout=240s
    ;;
  kube-dns-selector)
    kubectl -n kube-system patch service kube-dns -p '{"spec":{"selector":{"k8s-app":"kube-dns-v2"}}}'
    ;;
  client-dns-policy)
    kubectl -n "${Q3_NS}" delete pod client --ignore-not-found --wait=true >/dev/null
    kubectl -n "${Q3_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"client"},"spec":{"dnsPolicy":"Default","containers":[{"name":"shell","image":"busybox:1.36","command":["sleep","infinity"]}]}}'
    if ! kubectl -n "${Q3_NS}" wait --for=condition=Ready pod/client --timeout=180s; then
      kubectl -n "${Q3_NS}" describe pod/client >&2 || true
      exit 1
    fi
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

# The question only makes sense if the client really cannot resolve the name.
for _ in $(seq 1 60); do
  kubectl -n "${Q3_NS}" exec client -- wget -qO- -T 3 http://web 2>/dev/null | grep -q nginx || exit 0
  sleep 3
done
echo "the client still resolves web" >&2
exit 1
